/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

function isDigit(ch) {
  return ch !== undefined && ch >= '0' && ch <= '9';
}

function isIdentStart(ch) {
  return ch !== undefined && /[A-Za-z_]/.test(ch);
}

function isIdentChar(ch) {
  return ch !== undefined && /[A-Za-z0-9_]/.test(ch);
}

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  const len = input.length;
  let i = 0;

  while (i < len) {
    const ch = input[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    if (isDigit(ch) || (ch === '.' && isDigit(input[i + 1]))) {
      const start = i;
      let pos = i;

      while (pos < len && isDigit(input[pos])) pos += 1;

      let hasFrac = false;
      let fracDigits = 0;
      if (pos < len && input[pos] === '.') {
        hasFrac = true;
        pos += 1;
        const fracStart = pos;
        while (pos < len && isDigit(input[pos])) pos += 1;
        fracDigits = pos - fracStart;
      }

      if (hasFrac && fracDigits === 0) {
        throw new ExprError(`malformed number at ${start}`, start);
      }

      if (pos < len && (input[pos] === 'e' || input[pos] === 'E')) {
        pos += 1;
        if (pos < len && (input[pos] === '+' || input[pos] === '-')) pos += 1;
        const expStart = pos;
        while (pos < len && isDigit(input[pos])) pos += 1;
        if (pos - expStart === 0) {
          throw new ExprError(`malformed number at ${start}`, start);
        }
      }

      if (pos < len) {
        const trailing = input[pos];
        if (trailing === '.' || isIdentChar(trailing)) {
          throw new ExprError(`malformed number at ${start}`, start);
        }
      }

      const text = input.slice(start, pos);
      tokens.push({ type: 'number', value: Number(text), index: start });
      i = pos;
      continue;
    }

    if (isIdentStart(ch)) {
      const start = i;
      let pos = i + 1;
      while (pos < len && isIdentChar(input[pos])) pos += 1;
      tokens.push({ type: 'name', value: input.slice(start, pos), index: start });
      i = pos;
      continue;
    }

    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%' || ch === '^') {
      tokens.push({ type: 'operator', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen', value: '(', index: i });
      i += 1;
      continue;
    }

    if (ch === ')') {
      tokens.push({ type: 'rparen', value: ')', index: i });
      i += 1;
      continue;
    }

    if (ch === ',') {
      tokens.push({ type: 'comma', value: ',', index: i });
      i += 1;
      continue;
    }

    const codePoint = Array.from(input.slice(i))[0];
    throw new ExprError(`unexpected character '${codePoint}' at ${i}`, i);
  }

  return tokens;
}
"}

