      const start = i;
      let pos = i + 1;
      while (pos < len && isIdentChar(input[pos])) pos += 1;
      tokens.push({ type: 'name', value: input.slice(start, pos), index: start });
      i = pos;
      continue;
    }

    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%' || ch === '^') {
      tokens.push({ type: 'operator', value: ch, index: i });
      i += 1;
      continue;
    }

