{"file_path":"src/index.js","content":"/**
 * Arithmetic expression evaluator: tokeniser, precedence-climbing parser and a
 * tree walker with named constants, variables and a fixed function table.
 */

import { ExprError, tokenize } from './tokenize.js';
import { parse } from './parse.js';

export { ExprError, tokenize, parse };

const CONSTANTS = { pi: Math.PI, e: Math.E };

const FUNCTIONS = {
  abs: { arity: 1, fn: (a) => Math.abs(a) },
  sqrt: { arity: 1, fn: (a) => Math.sqrt(a) },
  floor: { arity: 1, fn: (a) => Math.floor(a) },
  ceil: { arity: 1, fn: (a) => Math.ceil(a) },
  round: { arity: 1, fn: (a) => Math.round(a) },
  sign: { arity: 1, fn: (a) => Math.sign(a) },
  pow: { arity: 2, fn: (a, b) => Math.pow(a, b) },
  atan2: { arity: 2, fn: (a, b) => Math.atan2(a, b) },
  min: { minArity: 1, fn: (...args) => Math.min(...args) },
  max: { minArity: 1, fn: (...args) => Math.max(...args) },
};

function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function resolveVariable(name, env, index) {
  if (Object.prototype.hasOwnProperty.call(env, name)) {
    const value = env[name];
    if (!isFiniteNumber(value)) {
      throw new ExprError(`variable ${name} is not a finite number at ${index}`, index);
    }
    return value;
  }
  if (Object.prototype.hasOwnProperty.call(CONSTANTS, name)) {
    return CONSTANTS[name];
  }
  throw new ExprError(`unknown variable: ${name} at ${index}`, index);
}

function evaluateNode(node, env) {
  switch (node.type) {
    case 'number':
      return node.value;

    case 'variable':
      return resolveVariable(node.name, env, node.index);

    case 'unary': {
      const operand = evaluateNode(node.operand, env);
      const result = node.op === '-' ? -operand : operand;
      if (!isFiniteNumber(result)) {
        throw new ExprError(`non-finite result at ${node.index}`, node.index);
      }
      return result;
    }

    case 'binary': {
      const left = evaluateNode(node.left, env);
      const right = evaluateNode(node.right, env);

      if ((node.op === '/' || node.op === '%') && right === 0) {
        throw new ExprError(`division by zero at ${node.index}`, node.index);
      }

      let result;
      switch (node.op) {
        case '+':
          result = left + right;
          break;
        case '-':
          result = left - right;
          break;
        case '*':
          result = left * right;
          break;
        case '/':
          result = left / right;
          break;
        case '%':
          result = left % right;
          break;
        case '^':
          result = Math.pow(left, right);
          break;
        default:
          throw new Error(`unreachable operator ${node.op}`);
